PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS erp_citizens(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,name TEXT NOT NULL,email TEXT,phone TEXT,document_hash TEXT,neighborhood TEXT,city TEXT,state TEXT,tags TEXT DEFAULT '[]',consent_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_citizens_office_name ON erp_citizens(office_id,name);
CREATE TABLE IF NOT EXISTS erp_demands(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,citizen_id TEXT REFERENCES erp_citizens(id) ON DELETE SET NULL,title TEXT NOT NULL,description TEXT DEFAULT '',category TEXT DEFAULT 'geral',priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN('baixa','normal','alta','urgente')),status TEXT NOT NULL DEFAULT 'aberta' CHECK(status IN('aberta','triagem','em_andamento','aguardando','resolvida','arquivada')),assignee_id TEXT,due_at TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_demands_office_status ON erp_demands(office_id,status,created_at DESC);
CREATE TABLE IF NOT EXISTS erp_services(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,citizen_id TEXT REFERENCES erp_citizens(id) ON DELETE SET NULL,demand_id TEXT REFERENCES erp_demands(id) ON DELETE SET NULL,channel TEXT NOT NULL DEFAULT 'presencial',notes TEXT DEFAULT '',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS erp_events(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT DEFAULT '',starts_at TEXT NOT NULL,ends_at TEXT,location TEXT,owner_id TEXT,status TEXT NOT NULL DEFAULT 'confirmado',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_events_office_start ON erp_events(office_id,starts_at);
CREATE TABLE IF NOT EXISTS erp_projects(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'planejamento',phase TEXT NOT NULL DEFAULT 'iniciacao',sponsor TEXT,objective TEXT DEFAULT '',scope TEXT DEFAULT '',owner_id TEXT,budget_cents INTEGER DEFAULT 0,progress INTEGER NOT NULL DEFAULT 0,starts_at TEXT,due_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS erp_audit(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,user_id TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT,metadata TEXT DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_audit_office_date ON erp_audit(office_id,created_at DESC);
CREATE TABLE IF NOT EXISTS erp_communications(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,title TEXT NOT NULL,channel TEXT NOT NULL DEFAULT 'social',status TEXT NOT NULL DEFAULT 'rascunho',content TEXT DEFAULT '',scheduled_at TEXT,owner_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_communications_office_status ON erp_communications(office_id,status,scheduled_at);
CREATE TABLE IF NOT EXISTS erp_tasks(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'hoje',priority TEXT NOT NULL DEFAULT 'normal',assigned_to TEXT,due_date TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_tasks_office_status ON erp_tasks(office_id,status,due_date);
CREATE TABLE IF NOT EXISTS erp_financial(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN('pagar','receber')),description TEXT NOT NULL,category TEXT DEFAULT 'geral',party TEXT,amount_cents INTEGER NOT NULL DEFAULT 0,due_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pendente',paid_at TEXT,notes TEXT DEFAULT '',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_financial_office_due ON erp_financial(office_id,type,status,due_date);
CREATE TABLE IF NOT EXISTS erp_project_stages(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,project_id TEXT NOT NULL REFERENCES erp_projects(id) ON DELETE CASCADE,phase TEXT NOT NULL,name TEXT NOT NULL,description TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'pendente',owner_id TEXT,starts_at TEXT,due_at TEXT,progress INTEGER NOT NULL DEFAULT 0,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_project_stages_project ON erp_project_stages(office_id,project_id,due_at);
CREATE TABLE IF NOT EXISTS erp_project_files(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,project_id TEXT NOT NULL REFERENCES erp_projects(id) ON DELETE CASCADE,stage_id TEXT REFERENCES erp_project_stages(id) ON DELETE CASCADE,object_key TEXT NOT NULL,file_name TEXT NOT NULL,content_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,uploaded_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_project_files_project ON erp_project_files(office_id,project_id,stage_id);
CREATE TABLE IF NOT EXISTS erp_relationships(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,person_name TEXT NOT NULL,stage TEXT NOT NULL DEFAULT 'prospect',channel TEXT DEFAULT 'presencial',owner_id TEXT,territory TEXT,next_action_at TEXT,notes TEXT DEFAULT '',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_relationships_stage ON erp_relationships(office_id,stage,next_action_at);
CREATE TABLE IF NOT EXISTS erp_field_actions(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,title TEXT NOT NULL,action_type TEXT NOT NULL DEFAULT 'mobilizacao',territory TEXT,owner_id TEXT,status TEXT NOT NULL DEFAULT 'planejada',target_contacts INTEGER NOT NULL DEFAULT 0,actual_contacts INTEGER NOT NULL DEFAULT 0,starts_at TEXT,notes TEXT DEFAULT '',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_field_actions_date ON erp_field_actions(office_id,status,starts_at);
CREATE TABLE IF NOT EXISTS erp_goals(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,title TEXT NOT NULL,metric TEXT NOT NULL,target_value REAL NOT NULL DEFAULT 0,current_value REAL NOT NULL DEFAULT 0,due_date TEXT,owner_id TEXT,status TEXT NOT NULL DEFAULT 'ativa',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_goals_status ON erp_goals(office_id,status,due_date);
